package com.inventra.backend.controller; import com.inventra.backend.dto.*; import com.inventra.backend.service.OrderService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;}@PostMapping public OrderResponse create(@Valid @RequestBody OrderRequest r){return s.create(r);}@GetMapping public List<OrderResponse> all(){return s.all();}@GetMapping("/{id}") public OrderResponse get(@PathVariable String id){return s.get(id);}@PostMapping("/{id}/cancel") public OrderResponse cancel(@PathVariable String id){return s.cancel(id);}@PostMapping("/{id}/fulfill") public OrderResponse fulfill(@PathVariable String id){return s.fulfill(id);}}
